def binary_search(a, x):
    """Return the index of x in the sorted list a, or -1."""
    lo, hi = 0, len(a) - 1
    while lo <= hi:
        mid = lo + (hi - lo) // 2   # overflow-safe form; see pitfall below
        if a[mid] == x:
            return mid
        if a[mid] < x:
            lo = mid + 1            # x can only be in the right half
        else:
            hi = mid - 1            # x can only be in the left half
    return -1

prices = [2, 5, 9, 14, 23, 37]
print(binary_search(prices, 23))   # 4
print(binary_search(prices, 10))   # -1, not present

